/**
 * Pricing Models Population Script
 *
 * The description of each pricing model that a pair names.
 *
 * Generated by projects/ores.seeder/datasets/ore_pricing_engines/generate_vocabulary_sql.py
 * from the ORE user guide. Do not edit it by hand: change the generator and run it again.
 * This script is idempotent.
 */

\echo '--- Pricing Models ---'

insert into ores_analytics_pricing_models_tbl (
    code, tenant_id, version, description, detail, source, modified_by, change_reason_code, change_commentary
) values
    ('Accrual', ores_utility_system_tenant_id_fn(), 0, 'Accrues a repo at its rate; no market model.', 'The repo value follows from accruing the cash and the security on the repo terms. No stochastic model and no volatility input are involved.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BGM', ores_utility_system_tenant_id_fn(), 0, 'Brace-Gatarek-Musiela market model for forward rates.', 'A LIBOR market model. ORE uses it in the range accrual pricer, which builds the model from the smile sections of the swaption volatility surface and prices each daily range observation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Black', ores_utility_system_tenant_id_fn(), 0, 'Black (1976) lognormal model on a forward.', 'Prices an option on a forward with a lognormal or shifted lognormal volatility. ORE reads the volatility from the market surface that the product names.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackBachelier', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier, chosen by the volatility input.', 'The swaption volatility surface decides the model. A lognormal or shifted lognormal surface prices with Black. A normal surface prices with Bachelier.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackOrBachelier', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier for coupon pricers, chosen by the volatility input.', 'The caplet volatility surface decides the model. A lognormal or shifted lognormal surface prices the capped and floored coupons with Black. A normal surface prices them with Bachelier.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackQuantoAdjusted', ores_utility_system_tenant_id_fn(), 0, 'Black model with a quanto adjustment from the FX-equity correlation.', 'Prices an equity coupon paid in another currency. The forward of the equity is adjusted with the FX volatility and the equity-FX correlation. A setting can switch the convexity adjustment off.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackScholes', ores_utility_system_tenant_id_fn(), 0, 'Black-Scholes model with a volatility surface and no dividend yield.', 'The classic lognormal model with a constant rate and volatility for each strike and expiry. The market volatility surface supplies the volatility.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackScholesMerton', ores_utility_system_tenant_id_fn(), 0, 'Black-Scholes model with a continuous dividend yield.', 'The Black-Scholes model for an equity that pays a continuous dividend yield. The forward of the equity follows from the equity curve and the dividend curve.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BrigoMercurio', ores_utility_system_tenant_id_fn(), 0, 'Lognormal model for CMS spread options, after Brigo and Mercurio.', 'Prices the spread of two constant maturity swap rates with two correlated lognormal variables. The reference is Brigo and Mercurio, Interest Rate Models - Theory and Practice, section 13.16.2.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CapFlooredNonStdYYModel', ores_utility_system_tenant_id_fn(), 0, 'Year-on-year inflation coupon model for non-standard legs.', 'Chooses a Black, unit displaced Black or Bachelier inflation coupon pricer from the volatility type of the market surface. The non-standard pricers handle coupons whose accrual does not follow the standard year-on-year timing.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CapFlooredYYModel', ores_utility_system_tenant_id_fn(), 0, 'Year-on-year inflation coupon model.', 'Chooses a Black, unit displaced Black or Bachelier year-on-year inflation coupon pricer from the volatility type of the market surface.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CpiCapModel', ores_utility_system_tenant_id_fn(), 0, 'CPI cap and floor model, Black or Bachelier.', 'Chooses the Black or the Bachelier CPI cap floor pricer from the volatility type of the market surface.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CrossAssetModel', ores_utility_system_tenant_id_fn(), 0, 'ORE cross asset model: Gaussian rates, FX, inflation, credit, equity and commodity.', 'Joins single-asset parametrizations with a correlation matrix. It can be one LGM model for one currency, a cross currency LGM model, or a model for rates, FX, inflation, credit, equity and commodity together. ORE uses it to simulate exposure, and with the MC and AMC engines to price products by Monte Carlo.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DefaultableEquityJumpDiffusion', ores_utility_system_tenant_id_fn(), 0, 'Equity jump-to-default model for convertible bonds.', 'The stock price follows a diffusion with a default intensity that depends on the stock price, and it jumps to zero at default. The model follows Andersen and Buffum, Calibration and Implementation of Convertible Bond Models (2002).', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountedCashflows', ores_utility_system_tenant_id_fn(), 0, 'Discounts the known cashflows; no stochastic model.', 'Projects each cashflow from the curves of the market and discounts it. The result needs no volatility. Credit-risky products also use the default curve and the recovery rate.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('GarmanKohlhagen', ores_utility_system_tenant_id_fn(), 0, 'Black-Scholes model for FX with a domestic and a foreign rate.', 'The Garman-Kohlhagen extension of Black-Scholes for a currency pair. The foreign rate takes the place of the dividend yield.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('GaussCopula', ores_utility_system_tenant_id_fn(), 0, 'One-factor Gaussian copula for credit index tranches.', 'Links the defaults of the names of an index with one common Gaussian factor. The tranche loss follows from the loss distribution of the pool.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Hagan', ores_utility_system_tenant_id_fn(), 0, 'Hagan replication pricers for constant maturity swap coupons.', 'Prices a CMS coupon by replicating the coupon with swaptions, after Hagan. The analytic pricer uses a closed-form approximation. The numerical pricer integrates numerically.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('IborCapModel', ores_utility_system_tenant_id_fn(), 0, 'Cap and floor model, Black or Bachelier.', 'Chooses the Black or the Bachelier cap floor engine from the volatility type of the market surface.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('LGM', ores_utility_system_tenant_id_fn(), 0, 'Linear Gauss Markov model, a one-factor Gaussian rates model.', 'A one-factor Gaussian short rate model in the form of Hagan. In ORE it is a cross asset model with one currency. Its state process always uses analytical moments, which makes simulation fast. ORE calibrates it to swaption prices.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('LinearTSR', ores_utility_system_tenant_id_fn(), 0, 'Linear terminal swap rate model for CMS convexity adjustments.', 'Models the annuity mapping as a linear function of the swap rate. The policy setting bounds the rates and the strikes of the replication.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('LognormalAdjustedIndexSpread', ores_utility_system_tenant_id_fn(), 0, 'Lognormal model for the spread of an index CDS.', 'Prices an option on an index CDS with a lognormal spread. The model adjusts the index spread for the front end protection.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('OneFactorCopula', ores_utility_system_tenant_id_fn(), 0, 'One-factor copula for cash flow CBO tranches.', 'Links the defaults in the pool of a collateralised bond obligation with one common factor and prices the tranches by Monte Carlo.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ScriptedTrade', ores_utility_system_tenant_id_fn(), 0, 'Scripted trade model; the script defines the payoff.', 'The scripted trade framework simulates the underlyings and evaluates the script of the trade. The model and engine settings come from the pricing engine configuration of the product type ScriptedTrade.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('YYCapModel', ores_utility_system_tenant_id_fn(), 0, 'Year-on-year inflation cap and floor model.', 'Chooses a Black, unit displaced Black or Bachelier year-on-year cap floor engine from the volatility type of the market surface.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary')
on conflict (tenant_id, code)
where valid_to = ores_utility_infinity_timestamp_fn()
do nothing;

select 'Pricing Models' as entity, count(*) as count
from ores_analytics_pricing_models_tbl
where valid_to = ores_utility_infinity_timestamp_fn();
